-- Additive control-center extension to the qualified v1/v2 controller.
CREATE TABLE IF NOT EXISTS control_missions(project TEXT PRIMARY KEY REFERENCES projects(id), document TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS control_brief_proposals(id TEXT PRIMARY KEY, project TEXT NOT NULL, task TEXT NOT NULL, brief TEXT NOT NULL REFERENCES briefs(id), author TEXT NOT NULL REFERENCES principals(id), rationale TEXT NOT NULL, state TEXT NOT NULL, FOREIGN KEY(project,task) REFERENCES tasks(project,id));
CREATE TABLE IF NOT EXISTS control_repairs(id TEXT PRIMARY KEY, project TEXT NOT NULL, task TEXT NOT NULL, candidate TEXT REFERENCES candidates(id), author TEXT NOT NULL REFERENCES principals(id), rationale TEXT NOT NULL, FOREIGN KEY(project,task) REFERENCES tasks(project,id));
CREATE TABLE IF NOT EXISTS control_questions(question TEXT PRIMARY KEY REFERENCES questions(id), attempt TEXT REFERENCES attempts(id), state TEXT NOT NULL DEFAULT 'persisted', delivery TEXT, lead_epoch INTEGER, acknowledgement TEXT, history TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS control_tool_calls(identity TEXT PRIMARY KEY, project TEXT NOT NULL REFERENCES projects(id), binding TEXT NOT NULL, epoch INTEGER NOT NULL, method TEXT NOT NULL, arguments TEXT NOT NULL, response TEXT);
CREATE TABLE IF NOT EXISTS control_ui_commands(identity TEXT PRIMARY KEY, project TEXT NOT NULL, binding TEXT NOT NULL, parameters TEXT NOT NULL, request TEXT NOT NULL, receipt TEXT);
CREATE TABLE IF NOT EXISTS control_ui_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, project TEXT NOT NULL, binding TEXT NOT NULL, digest TEXT NOT NULL, document TEXT NOT NULL, UNIQUE(binding,digest));
CREATE TABLE IF NOT EXISTS control_ui_cursors(binding TEXT NOT NULL, incarnation TEXT NOT NULL, method TEXT NOT NULL, cursor TEXT NOT NULL, PRIMARY KEY(binding,incarnation,method,cursor));
CREATE TABLE IF NOT EXISTS control_inventory_inputs(project TEXT NOT NULL REFERENCES projects(id), digest TEXT NOT NULL, bytes INTEGER NOT NULL, PRIMARY KEY(project,digest));
CREATE TABLE IF NOT EXISTS control_lead_streams(binding TEXT PRIMARY KEY REFERENCES codex_bindings(id), project TEXT NOT NULL REFERENCES projects(id), epoch INTEGER NOT NULL, source TEXT NOT NULL, ingested INTEGER NOT NULL DEFAULT 0, gap TEXT);
CREATE TABLE IF NOT EXISTS control_lead_inputs(seq INTEGER PRIMARY KEY AUTOINCREMENT, binding TEXT NOT NULL REFERENCES control_lead_streams(binding), item TEXT NOT NULL, turn TEXT NOT NULL, kind TEXT NOT NULL, source TEXT NOT NULL, artifact TEXT NOT NULL REFERENCES artifact_manifests(digest), bytes INTEGER NOT NULL, redaction TEXT NOT NULL, UNIQUE(binding,item));
CREATE TRIGGER IF NOT EXISTS control_lead_inputs_no_update BEFORE UPDATE ON control_lead_inputs BEGIN SELECT RAISE(ABORT,'immutable lead visible input'); END;
CREATE TRIGGER IF NOT EXISTS control_lead_inputs_no_delete BEFORE DELETE ON control_lead_inputs BEGIN SELECT RAISE(ABORT,'retained lead visible input'); END;
CREATE TABLE IF NOT EXISTS monitor_streams(id TEXT PRIMARY KEY, project TEXT NOT NULL, attempt TEXT NOT NULL REFERENCES attempts(id), epoch INTEGER NOT NULL, source TEXT NOT NULL, ingested INTEGER NOT NULL DEFAULT 0, byte_offset INTEGER NOT NULL DEFAULT 0, previous_digest TEXT NOT NULL DEFAULT '', reviewed_history INTEGER NOT NULL DEFAULT 0, reviewed_live INTEGER NOT NULL DEFAULT 0, segment TEXT NOT NULL, gap TEXT, last_ingested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS monitor_events(stream TEXT NOT NULL REFERENCES monitor_streams(id), item TEXT NOT NULL, ordinal INTEGER NOT NULL, document TEXT NOT NULL, input_digest TEXT NOT NULL, PRIMARY KEY(stream,item), UNIQUE(stream,ordinal));
CREATE TABLE IF NOT EXISTS monitor_native_inputs(stream TEXT NOT NULL, item TEXT NOT NULL, artifact TEXT NOT NULL REFERENCES artifact_manifests(digest), redaction TEXT NOT NULL, PRIMARY KEY(stream,item), FOREIGN KEY(stream,item) REFERENCES monitor_events(stream,item));
CREATE TABLE IF NOT EXISTS monitor_batches(id TEXT PRIMARY KEY, stream TEXT NOT NULL REFERENCES monitor_streams(id), lane TEXT NOT NULL CHECK(lane IN ('history','live')), predecessor INTEGER NOT NULL, through INTEGER NOT NULL, input_digest TEXT NOT NULL, inputs TEXT NOT NULL, intent TEXT NOT NULL, boundary TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'review-pending', UNIQUE(stream,lane,predecessor,through));
CREATE TABLE IF NOT EXISTS monitor_assessments(id TEXT PRIMARY KEY, batch TEXT NOT NULL REFERENCES monitor_batches(id), analyst TEXT NOT NULL, version TEXT NOT NULL, report TEXT NOT NULL, output_digest TEXT NOT NULL, UNIQUE(batch,analyst,version));
CREATE TABLE IF NOT EXISTS monitor_findings(id TEXT PRIMARY KEY, project TEXT NOT NULL, attempt TEXT NOT NULL REFERENCES attempts(id), epoch INTEGER NOT NULL, issue TEXT NOT NULL, criterion TEXT NOT NULL, document TEXT NOT NULL, assessment TEXT NOT NULL REFERENCES monitor_assessments(id), disposition TEXT NOT NULL DEFAULT 'advisory', adjudication TEXT, UNIQUE(project,attempt,criterion,issue));
CREATE TABLE IF NOT EXISTS monitor_credits(project TEXT NOT NULL, criterion TEXT NOT NULL, evidence TEXT NOT NULL, assessment TEXT NOT NULL REFERENCES monitor_assessments(id), PRIMARY KEY(project,criterion,evidence));
CREATE TABLE IF NOT EXISTS monitor_observers(principal TEXT PRIMARY KEY REFERENCES principals(id), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS monitor_corrections(id TEXT PRIMARY KEY, finding TEXT NOT NULL REFERENCES monitor_findings(id), project TEXT NOT NULL, attempt TEXT NOT NULL REFERENCES attempts(id), epoch INTEGER NOT NULL, decision TEXT NOT NULL, document TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'requested', operation TEXT, acknowledgement TEXT, resolution TEXT, UNIQUE(finding,epoch));
CREATE TRIGGER IF NOT EXISTS monitor_events_no_update BEFORE UPDATE ON monitor_events BEGIN SELECT RAISE(ABORT,'immutable visible input'); END;
CREATE TRIGGER IF NOT EXISTS monitor_events_no_delete BEFORE DELETE ON monitor_events BEGIN SELECT RAISE(ABORT,'retained visible input'); END;
CREATE TRIGGER IF NOT EXISTS monitor_assessments_no_update BEFORE UPDATE ON monitor_assessments BEGIN SELECT RAISE(ABORT,'immutable assessment'); END;
CREATE TRIGGER IF NOT EXISTS monitor_assessments_no_delete BEFORE DELETE ON monitor_assessments BEGIN SELECT RAISE(ABORT,'retained assessment'); END;
CREATE TRIGGER IF NOT EXISTS monitor_inputs_no_update BEFORE UPDATE ON monitor_native_inputs BEGIN SELECT RAISE(ABORT,'immutable retained input'); END;
CREATE TRIGGER IF NOT EXISTS monitor_inputs_no_delete BEFORE DELETE ON monitor_native_inputs BEGIN SELECT RAISE(ABORT,'retained input'); END;
CREATE TRIGGER IF NOT EXISTS monitor_batches_no_input_update BEFORE UPDATE OF stream,lane,predecessor,through,input_digest,inputs,intent,boundary ON monitor_batches BEGIN SELECT RAISE(ABORT,'immutable batch input'); END;
CREATE TRIGGER IF NOT EXISTS monitor_batches_no_delete BEFORE DELETE ON monitor_batches BEGIN SELECT RAISE(ABORT,'retained batch'); END;
